INSERT INTO `ai_task_records` VALUES ('43c764f3-04c4-497c-bb7a-41c39bc97d33','1b75660e-eb42-4287-8659-ff3dbc5813ea','similar','It is widely believed that regular exercise can ______ stress and improve sleep quality.','{\"items\": [{\"answer\": \"enhance\", \"question\": \"It is widely believed that a balanced diet can ______ overall health and boost energy levels.\", \"difficulty\": \"easy\", \"explanation\": \"Enhance means to improve or increase the quality of something. A balanced diet improves overall health and energy levels, similar to how exercise reduces stress.\"}, {\"answer\": \"alleviate\", \"question\": \"Research suggests that meditation can ______ anxiety and promote emotional well-being.\", \"difficulty\": \"medium\", \"explanation\": \"Alleviate means to make something less severe. Meditation reduces anxiety, similar to how exercise reduces stress.\"}, {\"answer\": \"enhance\", \"question\": \"Many studies indicate that adequate sleep can ______ cognitive function and memory retention.\", \"difficulty\": \"easy\", \"explanation\": \"Enhance means to improve. Adequate sleep improves cognitive function and memory, parallel to exercise improving sleep.\"}, {\"answer\": \"mitigate\", \"question\": \"It is commonly accepted that social support can ______ the impact of stress and foster resilience.\", \"difficulty\": \"medium\", \"explanation\": \"Mitigate means to make less severe. Social support reduces the impact of stress, similar to exercise reducing stress.\"}, {\"answer\": \"alleviate\", \"question\": \"Evidence shows that mindfulness practices can ______ symptoms of depression and enhance overall mood.\", \"difficulty\": \"medium\", \"explanation\": \"Alleviate means to reduce. Mindfulness reduces depression symptoms, analogous to exercise reducing stress.\"}, {\"answer\": \"reduce\", \"question\": \"It is well documented that exposure to nature can ______ mental fatigue and improve concentration.\", \"difficulty\": \"easy\", \"explanation\": \"Reduce means to make smaller. Nature exposure lessens mental fatigue, similar to how exercise reduces stress.\"}], \"fallback\": false, \"source_question\": \"It is widely believed that regular exercise can ______ stress and improve sleep quality.\"}','2026-07-15 12:53:40');
