INSERT INTO `exam_questions` VALUES ('8005d924-c6ea-421c-9261-8f6af2a83ca5','cet4','choice','medium','seed','It is widely believed that regular exercise can ______ stress and improve sleep quality.','[{\"key\": \"A\", \"text\": \"relieve\"}, {\"key\": \"B\", \"text\": \"release\"}, {\"key\": \"C\", \"text\": \"remove\"}, {\"key\": \"D\", \"text\": \"reduce\"}]','A','relieve stress 为固定搭配，表示缓解压力。','[\"vocabulary\", \"cet4\"]',1,'2026-07-15 12:53:34'),('8f1ace3b-2a50-4111-9eef-b68d801646f8','ncre2','choice','medium','seed','在 Python 中，下列哪个语句可以创建一个空字典？','[{\"key\": \"A\", \"text\": \"d = {}\"}, {\"key\": \"B\", \"text\": \"d = []\"}, {\"key\": \"C\", \"text\": \"d = ()\"}, {\"key\": \"D\", \"text\": \"d = set()\"}]','A','{} 创建空字典，[] 是列表，() 是元组，set() 是集合。','[\"python\", \"ncre2\"]',1,'2026-07-15 12:53:34'),('aa85d28d-b7cf-4731-beb5-3f3f009c4a13','cet4','choice','easy','seed','The research team has made significant progress in ______ renewable energy storage.','[{\"key\": \"A\", \"text\": \"developing\"}, {\"key\": \"B\", \"text\": \"developed\"}, {\"key\": \"C\", \"text\": \"develop\"}, {\"key\": \"D\", \"text\": \"development\"}]','A','has made progress in + V-ing 表示在某方面取得进展。','[\"grammar\", \"cet4\"]',1,'2026-07-15 12:53:34'),('d6205545-3682-40f8-9467-4e72be1ab4b2','ncre2','choice','easy','seed','SQL 中用于去除重复记录的关键字是？','[{\"key\": \"A\", \"text\": \"DISTINCT\"}, {\"key\": \"B\", \"text\": \"UNIQUE\"}, {\"key\": \"C\", \"text\": \"DIFFERENT\"}, {\"key\": \"D\", \"text\": \"ONLY\"}]','A','SELECT DISTINCT 用于返回唯一不同的值。','[\"sql\", \"ncre2\"]',1,'2026-07-15 12:53:34'),('e58e6187-eec1-4b4a-96d3-17b3c9cfefd5','cet6','choice','hard','seed','The committee\'s decision was ______ by a lack of empirical evidence.','[{\"key\": \"A\", \"text\": \"undermined\"}, {\"key\": \"B\", \"text\": \"underlined\"}, {\"key\": \"C\", \"text\": \"undertaken\"}, {\"key\": \"D\", \"text\": \"understood\"}]','A','undermine 表示削弱、动摇，符合语境。','[\"vocabulary\", \"cet6\"]',1,'2026-07-15 12:53:34');
/*!40000 ALTER TABLE `exam_questions` ENABLE KEYS */;
UNLOCK TABLES;

