INSERT INTO `generated_resources` VALUES ('04bc1361-6498-479d-9602-c4c9aa61390d','1b75660e-eb42-4287-8659-ff3dbc5813ea','osi-model','OSI 七层模型','reading','OSI 七层模型 拓展阅读','{\"materials\": [{\"title\": \"队列与栈的对比：从数据结构到应用场景\", \"summary\": \"详细对比队列（先进先出）和栈（后进先出）的定义、操作、实现方式及典型应用，帮助区分两者。\", \"keywords\": [\"队列\", \"栈\", \"FIFO\", \"LIFO\", \"数据结构\"], \"difficulty\": \"medium\"}, {\"title\": \"OSI七层模型中的数据结构应用\", \"summary\": \"介绍OSI模型中各层如何利用队列和栈进行数据封装、分段、缓冲等操作，加深对网络协议的理解。\", \"keywords\": [\"OSI模型\", \"数据封装\", \"缓冲区\", \"队列\", \"栈\"], \"difficulty\": \"medium\"}, {\"title\": \"练习题：队列与栈的区分\", \"summary\": \"提供一系列选择题和简答题，针对队列和栈的特性、操作结果进行练习，巩固概念。\", \"keywords\": [\"练习题\", \"队列\", \"栈\", \"区分\"], \"difficulty\": \"easy\"}], \"article\": \"## 深度阅读：OSI七层模型中的数据结构——队列与栈的应用\\n\\n在计算机网络中，OSI七层模型是理解网络通信的经典框架。每一层都有特定的功能，而这些功能的实现往往依赖于基本的数据结构，如队列和栈。对于计算机专业的学生，尤其是准备考试的同学，理解这些数据结构在协议栈中的应用，不仅能巩固概念，还能避免混淆。\\n\\n### 1. 队列（Queue）的应用：先进先出（FIFO）\\n队列是一种先进先出的线性表，允许在一端（队尾）插入，在另一端（队头）删除。在OSI模型中，队列常用于缓冲和调度：\\n- **数据链路层**：帧的发送和接收通常使用队列。当多个帧等待发送时，它们被放入发送队列，按顺序发送。接收端也会将接收到的帧放入队列，等待处理。\\n- **网络层**：路由器的分组转发使用队列。当多个分组同时到达同一输出端口时，它们被排队，按顺序转发。这保证了公平性和顺序性。\\n- **传输层**：TCP的发送和接收缓冲区本质上是队列。数据段按序发送，接收方按序重组。\\n\\n### 2. 栈（Stack）的应用：后进先出（LIFO）\\n栈是一种后进先出的线性表，只允许在一端（栈顶）进行插入和删除。在OSI模型中，栈常用于处理嵌套或递归结构：\\n- **表示层**：数据加密和解密过程中，可能使用栈来管理加密层级。例如，SSL/TLS协议中的证书链验证使用栈来跟踪证书路径。\\n- **应用层**：HTTP协议中的请求-响应模式不直接使用栈，但许多应用协议（如DNS）在递归查询时使用栈来保存中间结果。\\n- **协议栈本身**：OSI模型的分层结构本身就是一种栈的思想。数据从应用层向下传递到物理层，再向上传递，每一层添加或去除头部，类似于压栈和弹栈。\\n\\n### 3. 区分要点：操作顺序与使用场景\\n- **队列**：强调顺序性，适用于需要按到达顺序处理的场景，如缓冲、调度、流水线。\\n- **栈**：强调后进先出，适用于需要回溯、撤销、递归的场景，如函数调用、括号匹配、深度优先搜索。\\n\\n在OSI模型中，数据封装过程更像栈（后进先出），而数据转发过程更像队列（先进先出）。理解这一点，有助于避免概念混淆。\\n\\n### 4. 考试提示\\n在考试中，常见题型包括：描述某一层的数据结构应用、比较队列和栈的异同、分析协议栈中的压栈/弹栈过程。建议结合具体协议（如TCP、IP、以太网）来记忆，并多做练习题巩固。\\n\\n通过以上分析，希望你能清晰区分队列和栈，并在OSI模型中找到它们的实际身影。\"}','{\"article\": \"## 深度阅读：OSI七层模型中的数据结构——队列与栈的应用\\n\\n在计算机网络中，OSI七层模型是理解网络通信的经典框架。每一层都有特定的功能，而这些功能的实现往往依赖于基本的数据结构，如队列和栈。对于计算机专业的学生，尤其是准备考试的同学，理解这些数据结构在协议栈中的应用，不仅能巩固概念，还能避免混淆。\\n\\n### 1. 队列（Queue）的应用：先进先出（FIFO）\\n队列是一种先进先出的线性表，允许在一端（队尾）插入，在另一端（队头）删除。在OSI模型中，队列常用于缓冲和调度：\\n- **数据链路层**：帧的发送和接收通常使用队列。当多个帧等待发送时，它们被放入发送队列，按顺序发送。接收端也会将接收到的帧放入队列，等待处理。\\n- **网络层**：路由器的分组转发使用队列。当多个分组同时到达同一输出端口时，它们被排队，按顺序转发。这保证了公平性和顺序性。\\n- **传输层**：TCP的发送和接收缓冲区本质上是队列。数据段按序发送，接收方按序重组。\\n\\n### 2. 栈（Stack）的应用：后进先出（LIFO）\\n栈是一种后进先出的线性表，只允许在一端（栈顶）进行插入和删除。在OSI模型中，栈常用于处理嵌套或递归结构：\\n- **表示层**：数据加密和解密过程中，可能使用栈来管理加密层级。例如，SSL/TLS协议中的证书链验证使用栈来跟踪证书路径。\\n- **应用层**：HTTP协议中的请求-响应模式不直接使用栈，但许多应用协议（如DNS）在递归查询时使用栈来保存中间结果。\\n- **协议栈本身**：OSI模型的分层结构本身就是一种栈的思想。数据从应用层向下传递到物理层，再向上传递，每一层添加或去除头部，类似于压栈和弹栈。\\n\\n### 3. 区分要点：操作顺序与使用场景\\n- **队列**：强调顺序性，适用于需要按到达顺序处理的场景，如缓冲、调度、流水线。\\n- **栈**：强调后进先出，适用于需要回溯、撤销、递归的场景，如函数调用、括号匹配、深度优先搜索。\\n\\n在OSI模型中，数据封装过程更像栈（后进先出），而数据转发过程更像队列（先进先出）。理解这一点，有助于避免概念混淆。\\n\\n### 4. 考试提示\\n在考试中，常见题型包括：描述某一层的数据结构应用、比较队列和栈的异同、分析协议栈中的压栈/弹栈过程。建议结合具体协议（如TCP、IP、以太网）来记忆，并多做练习题巩固。\\n\\n通过以上分析，希望你能清晰区分队列和栈，并在OSI模型中找到它们的实际身影。\", \"materials\": [{\"title\": \"队列与栈的对比：从数据结构到应用场景\", \"summary\": \"详细对比队列（先进先出）和栈（后进先出）的定义、操作、实现方式及典型应用，帮助区分两者。\", \"keywords\": [\"队列\", \"栈\", \"FIFO\", \"LIFO\", \"数据结构\"], \"difficulty\": \"medium\"}, {\"title\": \"OSI七层模型中的数据结构应用\", \"summary\": \"介绍OSI模型中各层如何利用队列和栈进行数据封装、分段、缓冲等操作，加深对网络协议的理解。\", \"keywords\": [\"OSI模型\", \"数据封装\", \"缓冲区\", \"队列\", \"栈\"], \"difficulty\": \"medium\"}, {\"title\": \"练习题：队列与栈的区分\", \"summary\": \"提供一系列选择题和简答题，针对队列和栈的特性、操作结果进行练习，巩固概念。\", \"keywords\": [\"练习题\", \"队列\", \"栈\", \"区分\"], \"difficulty\": \"easy\"}]}','2026-07-16 17:05:51'),('059cdd0c-5d56-4299-902b-5996c46940c5','1b75660e-eb42-4287-8659-ff3dbc5813ea','index','索引与 B+ 树','code','索引与 B+ 树 代码实操','{\"language\": \"python\", \"code\": \"import bisect\\n\\nclass BPlusTreeNode:\\n    def __init__(self, leaf=False):\\n        self.leaf = leaf\\n        self.keys = []\\n        self.children = []\\n\\nclass BPlusTree:\\n    def __init__(self, order=4):\\n        self.root = BPlusTreeNode(leaf=True)\\n        self.order = order  # 最大子节点数\\n\\n    def search(self, key):\\n        \\\"\\\"\\\"查找key，返回是否找到\\\"\\\"\\\"\\n        node = self.root\\n        while not node.leaf:\\n            i = bisect.bisect_left(node.keys, key)\\n            node = node.children[i]\\n        i = bisect.bisect_left(node.keys, key)\\n        return i < len(node.keys) and node.keys[i] == key\\n\\n    def insert(self, key):\\n        \\\"\\\"\\\"插入key\\\"\\\"\\\"\\n        root = self.root\\n        if len(root.keys) == self.order - 1:\\n            new_root = BPlusTreeNode()\\n            new_root.children.append(root)\\n            self._split_child(new_root, 0)\\n            self.root = new_root\\n        self._insert_non_full(self.root, key)\\n\\n    def _insert_non_full(self, node, key):\\n        if node.leaf:\\n            i = bisect.bisect_left(node.keys, key)\\n            node.keys.insert(i, key)\\n        else:\\n            i = bisect.bisect_left(node.keys, key)\\n            if len(node.children[i].keys) == self.order - 1:\\n                self._split_child(node, i)\\n                if key > node.keys[i]:\\n                    i += 1\\n            self._insert_non_full(node.children[i], key)\\n\\n    def _split_child(self, parent, i):\\n        order = self.order\\n        child = parent.children[i]\\n        mid = order // 2\\n        new_node = BPlusTreeNode(leaf=child.leaf)\\n        parent.keys.insert(i, child.keys[mid])\\n        parent.children.insert(i + 1, new_node)\\n        new_node.keys = child.keys[mid + (0 if child.leaf else 1):]\\n        child.keys = child.keys[:mid]\\n        if not child.leaf:\\n            new_node.children = child.children[mid + 1:]\\n            child.children = child.children[:mid + 1]\\n\\n    def display(self):\\n        \\\"\\\"\\\"层次遍历打印树\\\"\\\"\\\"\\n        queue = [self.root]\\n        while queue:\\n            level = []\\n            for _ in range(len(queue)):\\n                node = queue.pop(0)\\n                level.append(node.keys)\\n                if not node.leaf:\\n                    queue.extend(node.children)\\n            print(level)\\n\\n# 使用示例\\nif __name__ == \'__main__\':\\n    bpt = BPlusTree(order=4)\\n    keys = [10, 20, 5, 6, 12, 30, 7, 17]\\n    for k in keys:\\n        bpt.insert(k)\\n    bpt.display()\\n    print(\\\"Search 12:\\\", bpt.search(12))\\n    print(\\\"Search 15:\\\", bpt.search(15))\", \"explanation\": \"运行说明：直接运行代码，会插入一组键并打印B+树结构，然后测试搜索功能。\", \"exercise\": \"课后练习任务：\\n1. 修改代码，添加删除操作（delete方法）。\\n2. 实现范围查询（range_query(low, high)），返回所有在[low, high]内的键。\\n3. 分析当前实现中，当叶子节点分裂时如何处理重复键？如何改进？\"}','{\"code\": \"import bisect\\n\\nclass BPlusTreeNode:\\n    def __init__(self, leaf=False):\\n        self.leaf = leaf\\n        self.keys = []\\n        self.children = []\\n\\nclass BPlusTree:\\n    def __init__(self, order=4):\\n        self.root = BPlusTreeNode(leaf=True)\\n        self.order = order  # 最大子节点数\\n\\n    def search(self, key):\\n        \\\"\\\"\\\"查找key，返回是否找到\\\"\\\"\\\"\\n        node = self.root\\n        while not node.leaf:\\n            i = bisect.bisect_left(node.keys, key)\\n            node = node.children[i]\\n        i = bisect.bisect_left(node.keys, key)\\n        return i < len(node.keys) and node.keys[i] == key\\n\\n    def insert(self, key):\\n        \\\"\\\"\\\"插入key\\\"\\\"\\\"\\n        root = self.root\\n        if len(root.keys) == self.order - 1:\\n            new_root = BPlusTreeNode()\\n            new_root.children.append(root)\\n            self._split_child(new_root, 0)\\n            self.root = new_root\\n        self._insert_non_full(self.root, key)\\n\\n    def _insert_non_full(self, node, key):\\n        if node.leaf:\\n            i = bisect.bisect_left(node.keys, key)\\n            node.keys.insert(i, key)\\n        else:\\n            i = bisect.bisect_left(node.keys, key)\\n            if len(node.children[i].keys) == self.order - 1:\\n                self._split_child(node, i)\\n                if key > node.keys[i]:\\n                    i += 1\\n            self._insert_non_full(node.children[i], key)\\n\\n    def _split_child(self, parent, i):\\n        order = self.order\\n        child = parent.children[i]\\n        mid = order // 2\\n        new_node = BPlusTreeNode(leaf=child.leaf)\\n        parent.keys.insert(i, child.keys[mid])\\n        parent.children.insert(i + 1, new_node)\\n        new_node.keys = child.keys[mid + (0 if child.leaf else 1):]\\n        child.keys = child.keys[:mid]\\n        if not child.leaf:\\n            new_node.children = child.children[mid + 1:]\\n            child.children = child.children[:mid + 1]\\n\\n    def display(self):\\n        \\\"\\\"\\\"层次遍历打印树\\\"\\\"\\\"\\n        queue = [self.root]\\n        while queue:\\n            level = []\\n            for _ in range(len(queue)):\\n                node = queue.pop(0)\\n                level.append(node.keys)\\n                if not node.leaf:\\n                    queue.extend(node.children)\\n            print(level)\\n\\n# 使用示例\\nif __name__ == \'__main__\':\\n    bpt = BPlusTree(order=4)\\n    keys = [10, 20, 5, 6, 12, 30, 7, 17]\\n    for k in keys:\\n        bpt.insert(k)\\n    bpt.display()\\n    print(\\\"Search 12:\\\", bpt.search(12))\\n    print(\\\"Search 15:\\\", bpt.search(15))\", \"quality\": {\"accuracy\": 4, \"rationale\": \"代码实现了B+树基本操作，但缺少删除和范围查询，且分裂逻辑对重复键处理不明确；适合实践型学生，但需补充细节。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 4, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 2}, \"exercise\": \"课后练习任务：\\n1. 修改代码，添加删除操作（delete方法）。\\n2. 实现范围查询（range_query(low, high)），返回所有在[low, high]内的键。\\n3. 分析当前实现中，当叶子节点分裂时如何处理重复键？如何改进？\", \"language\": \"python\", \"explanation\": \"运行说明：直接运行代码，会插入一组键并打印B+树结构，然后测试搜索功能。\"}','2026-07-19 09:45:55'),('112ee382-cbde-472e-a073-1eed831e74fa','1b75660e-eb42-4287-8659-ff3dbc5813ea','index','索引与 B+ 树','mindmap','索引与 B+ 树 思维导图','{\"name\": \"索引与B+树\", \"children\": [{\"name\": \"索引基础\", \"children\": [{\"name\": \"索引概念\", \"children\": [{\"name\": \"定义与作用\"}, {\"name\": \"分类：聚簇/非聚簇\"}]}, {\"name\": \"索引实现方式\", \"children\": [{\"name\": \"哈希索引\"}, {\"name\": \"B+树索引\"}]}]}, {\"name\": \"B+树结构\", \"children\": [{\"name\": \"节点类型\", \"children\": [{\"name\": \"内部节点\"}, {\"name\": \"叶子节点\"}]}, {\"name\": \"关键性质\", \"children\": [{\"name\": \"平衡性\"}, {\"name\": \"扇出与高度\"}]}]}, {\"name\": \"B+树操作\", \"children\": [{\"name\": \"查询操作\", \"children\": [{\"name\": \"单值查询\"}, {\"name\": \"范围查询\"}]}, {\"name\": \"更新操作\", \"children\": [{\"name\": \"插入与分裂\"}, {\"name\": \"删除与合并\"}]}]}, {\"name\": \"实践应用\", \"children\": [{\"name\": \"数据库索引设计\", \"children\": [{\"name\": \"主键索引\"}, {\"name\": \"复合索引\"}]}, {\"name\": \"性能优化\", \"children\": [{\"name\": \"索引代价\"}, {\"name\": \"查询计划\"}]}]}]}','{\"tree\": {\"name\": \"索引与B+树\", \"children\": [{\"name\": \"索引基础\", \"children\": [{\"name\": \"索引概念\", \"children\": [{\"name\": \"定义与作用\"}, {\"name\": \"分类：聚簇/非聚簇\"}]}, {\"name\": \"索引实现方式\", \"children\": [{\"name\": \"哈希索引\"}, {\"name\": \"B+树索引\"}]}]}, {\"name\": \"B+树结构\", \"children\": [{\"name\": \"节点类型\", \"children\": [{\"name\": \"内部节点\"}, {\"name\": \"叶子节点\"}]}, {\"name\": \"关键性质\", \"children\": [{\"name\": \"平衡性\"}, {\"name\": \"扇出与高度\"}]}]}, {\"name\": \"B+树操作\", \"children\": [{\"name\": \"查询操作\", \"children\": [{\"name\": \"单值查询\"}, {\"name\": \"范围查询\"}]}, {\"name\": \"更新操作\", \"children\": [{\"name\": \"插入与分裂\"}, {\"name\": \"删除与合并\"}]}]}, {\"name\": \"实践应用\", \"children\": [{\"name\": \"数据库索引设计\", \"children\": [{\"name\": \"主键索引\"}, {\"name\": \"复合索引\"}]}, {\"name\": \"性能优化\", \"children\": [{\"name\": \"索引代价\"}, {\"name\": \"查询计划\"}]}]}]}, \"quality\": {\"accuracy\": 5, \"rationale\": \"内容准确全面，结构清晰，适合计算机专业大二学生，但缺少实践案例和与网络基础、排序算法的关联。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}}','2026-07-19 09:45:26'),('16a8d9dc-1aaf-4f8d-bd74-af13569b4626','1b75660e-eb42-4287-8659-ff3dbc5813ea','binary-tree','二叉树','quiz','二叉树 练习题','{\"questions\": [{\"type\": \"choice\", \"question\": \"在二叉树中，度为2的节点数比叶子节点数少1，该性质适用于哪种二叉树？\", \"options\": [\"满二叉树\", \"完全二叉树\", \"任何二叉树\", \"二叉搜索树\"], \"answer\": \"任何二叉树\", \"explanation\": \"对于任何非空二叉树，叶子节点数 = 度为2的节点数 + 1，这是二叉树的一个基本性质。\", \"difficulty\": \"easy\"}, {\"type\": \"blank\", \"question\": \"一棵完全二叉树有1000个节点，则叶子节点个数为____。\", \"answer\": \"500\", \"explanation\": \"完全二叉树中，叶子节点数 = floor((节点数+1)/2) = floor(1001/2)=500。\", \"difficulty\": \"medium\"}, {\"type\": \"code\", \"question\": \"给定二叉树节点定义如下，请实现函数 `int countNodes(TreeNode* root)` 返回节点总数。\\n```cpp\\nstruct TreeNode {\\n    int val;\\n    TreeNode *left;\\n    TreeNode *right;\\n    TreeNode(int x) : val(x), left(NULL), right(NULL) {}\\n};\\n```\", \"answer\": \"int countNodes(TreeNode* root) { if (!root) return 0; return 1 + countNodes(root->left) + countNodes(root->right); }\", \"explanation\": \"递归计算：空节点返回0，否则返回1加上左右子树节点数。\", \"difficulty\": \"easy\"}, {\"type\": \"case\", \"question\": \"给定二叉树的前序遍历序列为 [1,2,4,5,3,6,7]，中序遍历序列为 [4,2,5,1,6,3,7]。请重建该二叉树并输出后序遍历序列。\", \"answer\": \"[4,5,2,6,7,3,1]\", \"explanation\": \"前序第一个为根1，中序中1左边为左子树[4,2,5]，右边为右子树[6,3,7]。递归构建，后序为左右根。\", \"difficulty\": \"hard\"}]}','{\"quality\": {\"accuracy\": 5, \"rationale\": \"知识准确，题目覆盖基础性质、完全二叉树计算、递归实现和树重建，贴合计算机专业大二学生，结构完整，无幻觉风险。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"questions\": [{\"type\": \"choice\", \"answer\": \"任何二叉树\", \"options\": [\"满二叉树\", \"完全二叉树\", \"任何二叉树\", \"二叉搜索树\"], \"question\": \"在二叉树中，度为2的节点数比叶子节点数少1，该性质适用于哪种二叉树？\", \"difficulty\": \"easy\", \"explanation\": \"对于任何非空二叉树，叶子节点数 = 度为2的节点数 + 1，这是二叉树的一个基本性质。\"}, {\"type\": \"blank\", \"answer\": \"500\", \"question\": \"一棵完全二叉树有1000个节点，则叶子节点个数为____。\", \"difficulty\": \"medium\", \"explanation\": \"完全二叉树中，叶子节点数 = floor((节点数+1)/2) = floor(1001/2)=500。\"}, {\"type\": \"code\", \"answer\": \"int countNodes(TreeNode* root) { if (!root) return 0; return 1 + countNodes(root->left) + countNodes(root->right); }\", \"question\": \"给定二叉树节点定义如下，请实现函数 `int countNodes(TreeNode* root)` 返回节点总数。\\n```cpp\\nstruct TreeNode {\\n    int val;\\n    TreeNode *left;\\n    TreeNode *right;\\n    TreeNode(int x) : val(x), left(NULL), right(NULL) {}\\n};\\n```\", \"difficulty\": \"easy\", \"explanation\": \"递归计算：空节点返回0，否则返回1加上左右子树节点数。\"}, {\"type\": \"case\", \"answer\": \"[4,5,2,6,7,3,1]\", \"question\": \"给定二叉树的前序遍历序列为 [1,2,4,5,3,6,7]，中序遍历序列为 [4,2,5,1,6,3,7]。请重建该二叉树并输出后序遍历序列。\", \"difficulty\": \"hard\", \"explanation\": \"前序第一个为根1，中序中1左边为左子树[4,2,5]，右边为右子树[6,3,7]。递归构建，后序为左右根。\"}]}','2026-07-19 09:48:16'),('18c41a31-4ec8-4559-a981-74b0efe410a6','1b75660e-eb42-4287-8659-ff3dbc5813ea','binary-tree','二叉树','reading','二叉树 拓展阅读','{\"materials\": [{\"title\": \"二叉树遍历的递归与非递归实现\", \"summary\": \"详细讲解二叉树的前序、中序、后序遍历的递归与非递归实现，包括代码示例和复杂度分析。\", \"keywords\": [\"二叉树\", \"遍历\", \"递归\", \"非递归\", \"栈\"], \"difficulty\": \"medium\"}, {\"title\": \"二叉搜索树与平衡二叉树\", \"summary\": \"介绍二叉搜索树的定义、操作（查找、插入、删除）以及平衡二叉树（AVL树）的概念和旋转操作。\", \"keywords\": [\"二叉搜索树\", \"平衡二叉树\", \"AVL树\", \"旋转\"], \"difficulty\": \"medium\"}, {\"title\": \"堆与优先队列\", \"summary\": \"讲解堆（最大堆、最小堆）的实现，以及如何用堆实现优先队列，包括堆排序的应用。\", \"keywords\": [\"堆\", \"优先队列\", \"堆排序\", \"完全二叉树\"], \"difficulty\": \"medium\"}], \"article\": \"# 二叉树深度阅读\\n\\n## 1. 二叉树的定义与性质\\n二叉树是每个节点最多有两个子树的树结构，通常子树被称作“左子树”和“右子树”。二叉树具有以下重要性质：\\n- 第 i 层最多有 2^(i-1) 个节点（i≥1）。\\n- 深度为 k 的二叉树最多有 2^k - 1 个节点。\\n- 对任何一棵二叉树，叶子节点数 n0 与度为2的节点数 n2 满足 n0 = n2 + 1。\\n- 完全二叉树和满二叉树是两种特殊形式，常用于堆等数据结构。\\n\\n## 2. 二叉树的存储结构\\n二叉树可以用顺序存储（数组）或链式存储（节点结构体）实现。顺序存储适合完全二叉树，链式存储更通用。\\n\\n## 3. 二叉树的遍历\\n- **前序遍历**：根 -> 左 -> 右。递归实现简单，非递归需借助栈。\\n- **中序遍历**：左 -> 根 -> 右。非递归实现需模拟递归栈。\\n- **后序遍历**：左 -> 右 -> 根。非递归实现较复杂，可用两个栈或标记法。\\n- **层序遍历**：借助队列，按层输出。\\n\\n## 4. 二叉搜索树（BST）\\nBST 要求左子树所有节点值小于根节点，右子树所有节点值大于根节点。查找、插入、删除的平均时间复杂度为 O(log n)，最坏退化为 O(n)。\\n\\n## 5. 平衡二叉树（AVL树）\\nAVL树是自平衡二叉搜索树，任何节点的左右子树高度差不超过1。插入和删除后通过旋转（左旋、右旋、左右旋、右左旋）保持平衡，保证 O(log n) 的查找性能。\\n\\n## 6. 堆\\n堆是一种完全二叉树，最大堆的父节点值大于等于子节点，最小堆反之。堆常用于实现优先队列，堆排序利用最大堆进行排序，时间复杂度 O(n log n)。\\n\\n## 7. 实践建议\\n- 动手实现二叉树的遍历代码，尤其是非递归版本。\\n- 练习 BST 的插入和删除操作，理解平衡旋转。\\n- 用堆实现一个优先队列，并尝试堆排序。\\n\\n通过以上学习，你将掌握二叉树的核心概念和常见操作，为后续学习图论、数据库索引等打下坚实基础。\"}','{\"article\": \"# 二叉树深度阅读\\n\\n## 1. 二叉树的定义与性质\\n二叉树是每个节点最多有两个子树的树结构，通常子树被称作“左子树”和“右子树”。二叉树具有以下重要性质：\\n- 第 i 层最多有 2^(i-1) 个节点（i≥1）。\\n- 深度为 k 的二叉树最多有 2^k - 1 个节点。\\n- 对任何一棵二叉树，叶子节点数 n0 与度为2的节点数 n2 满足 n0 = n2 + 1。\\n- 完全二叉树和满二叉树是两种特殊形式，常用于堆等数据结构。\\n\\n## 2. 二叉树的存储结构\\n二叉树可以用顺序存储（数组）或链式存储（节点结构体）实现。顺序存储适合完全二叉树，链式存储更通用。\\n\\n## 3. 二叉树的遍历\\n- **前序遍历**：根 -> 左 -> 右。递归实现简单，非递归需借助栈。\\n- **中序遍历**：左 -> 根 -> 右。非递归实现需模拟递归栈。\\n- **后序遍历**：左 -> 右 -> 根。非递归实现较复杂，可用两个栈或标记法。\\n- **层序遍历**：借助队列，按层输出。\\n\\n## 4. 二叉搜索树（BST）\\nBST 要求左子树所有节点值小于根节点，右子树所有节点值大于根节点。查找、插入、删除的平均时间复杂度为 O(log n)，最坏退化为 O(n)。\\n\\n## 5. 平衡二叉树（AVL树）\\nAVL树是自平衡二叉搜索树，任何节点的左右子树高度差不超过1。插入和删除后通过旋转（左旋、右旋、左右旋、右左旋）保持平衡，保证 O(log n) 的查找性能。\\n\\n## 6. 堆\\n堆是一种完全二叉树，最大堆的父节点值大于等于子节点，最小堆反之。堆常用于实现优先队列，堆排序利用最大堆进行排序，时间复杂度 O(n log n)。\\n\\n## 7. 实践建议\\n- 动手实现二叉树的遍历代码，尤其是非递归版本。\\n- 练习 BST 的插入和删除操作，理解平衡旋转。\\n- 用堆实现一个优先队列，并尝试堆排序。\\n\\n通过以上学习，你将掌握二叉树的核心概念和常见操作，为后续学习图论、数据库索引等打下坚实基础。\", \"quality\": {\"accuracy\": 5, \"rationale\": \"内容准确全面，涵盖二叉树核心知识点，与计算机专业大二学生背景匹配，结构完整，无幻觉风险。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"materials\": [{\"title\": \"二叉树遍历的递归与非递归实现\", \"summary\": \"详细讲解二叉树的前序、中序、后序遍历的递归与非递归实现，包括代码示例和复杂度分析。\", \"keywords\": [\"二叉树\", \"遍历\", \"递归\", \"非递归\", \"栈\"], \"difficulty\": \"medium\"}, {\"title\": \"二叉搜索树与平衡二叉树\", \"summary\": \"介绍二叉搜索树的定义、操作（查找、插入、删除）以及平衡二叉树（AVL树）的概念和旋转操作。\", \"keywords\": [\"二叉搜索树\", \"平衡二叉树\", \"AVL树\", \"旋转\"], \"difficulty\": \"medium\"}, {\"title\": \"堆与优先队列\", \"summary\": \"讲解堆（最大堆、最小堆）的实现，以及如何用堆实现优先队列，包括堆排序的应用。\", \"keywords\": [\"堆\", \"优先队列\", \"堆排序\", \"完全二叉树\"], \"difficulty\": \"medium\"}]}','2026-07-19 09:48:24'),('1d6850e7-ccab-4987-86d8-dff410846b12','1b75660e-eb42-4287-8659-ff3dbc5813ea','binary-tree','二叉树','doc','二叉树 讲解文档','# 二叉树：数据结构与算法星系\n\n## 核心概念\n\n二叉树是每个节点最多有两个子树的树结构，分别称为左子树和右子树。它是计算机科学中最基础且应用最广泛的数据结构之一，为高效查找、排序和索引提供了基础。\n\n**关键术语：**\n- **根节点**：树的最顶层节点\n- **叶子节点**：没有子节点的节点\n- **子树**：节点及其所有后代构成的树\n- **深度**：从根到某节点的路径长度\n- **高度**：从某节点到最远叶子节点的路径长度\n\n## 原理讲解\n\n### 二叉树的特性\n1. **递归结构**：每个节点本身也是一棵二叉树的根\n2. **有序性**：左子树所有节点 < 根节点 < 右子树所有节点（针对二叉搜索树）\n3. **遍历方式**：\n   - 前序：根 → 左 → 右\n   - 中序：左 → 根 → 右（二叉搜索树的中序遍历得到有序序列）\n   - 后序：左 → 右 → 根\n   - 层序：逐层从左到右\n\n### 存储方式\n- **链式存储**：每个节点包含数据、左指针、右指针\n- **顺序存储**：用数组存储，适用于完全二叉树\n\n### 时间复杂度分析\n| 操作 | 平均情况 | 最坏情况 |\n|------|---------|---------|\n| 查找 | O(log n) | O(n) |\n| 插入 | O(log n) | O(n) |\n| 删除 | O(log n) | O(n) |\n\n*注：最坏情况发生在树退化为链表时（如插入有序数据）*\n\n## 案例\n\n### 案例1：二叉搜索树的插入操作\n**场景**：构建一个二叉搜索树，依次插入 [5, 3, 7, 2, 4, 6, 8]\n\n**过程**：\n1. 插入5 → 根节点\n2. 插入3 → 3<5，成为左子节点\n3. 插入7 → 7>5，成为右子节点\n4. 插入2 → 2<5→2<3，成为3的左子节点\n5. 插入4 → 4<5→4>3，成为3的右子节点\n6. 插入6 → 6>5→6<7，成为7的左子节点\n7. 插入8 → 8>5→8>7，成为7的右子节点\n\n**最终树结构**：\n```\n      5\n     / \\\n    3   7\n   / \\ / \\\n  2  4 6  8\n```\n\n### 案例2：中序遍历验证有序性\n对上述树进行中序遍历：\n- 左子树：2→3→4\n- 根：5\n- 右子树：6→7→8\n**结果**：[2, 3, 4, 5, 6, 7, 8] ✓ 完全有序\n\n### 案例3：查找操作\n**查找6**：\n1. 比较5 → 6>5，进入右子树\n2. 比较7 → 6<7，进入左子树\n3. 比较6 → 找到！仅需3次比较\n\n**查找9**：\n1. 比较5 → 9>5，进入右子树\n2. 比较7 → 9>7，进入右子树\n3. 比较8 → 9>8，右子树为空 → 未找到，需3次比较\n\n## 总结\n\n二叉树是计算机专业大二阶段必须掌握的核心数据结构，它完美体现了递归思想和分治策略。作为实践型学习者，建议你：\n\n1. **动手编码**：用Python/C++实现二叉树的插入、查找、删除和三种遍历\n2. **对比学习**：将二叉树与已掌握的关系模型（数据库索引常用B+树）和排序算法（归并排序的递归思想）联系起来\n3. **应用场景**：理解BST在数据库索引、表达式求值、哈夫曼编码中的实际应用\n4. **进阶方向**：学习平衡二叉树（AVL、红黑树）解决BST退化问题\n\n**每周2小时建议分配**：\n- 第1小时：理解原理 + 手动画图模拟操作\n- 第2小时：编码实现 + LeetCode简单题练习（如#94二叉树中序遍历）\n\n记住：二叉树不仅是考试重点，更是理解更复杂树结构（如B树、Trie树）的基础。多画图、多编码，你一定能掌握！','{\"quality\": {\"accuracy\": 5, \"rationale\": \"内容准确全面，结构清晰，案例丰富，贴合计算机大二学生背景，但未针对未知的学习目标和错误倾向做个性化调整。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}}','2026-07-19 09:48:04'),('24533493-25c4-4deb-af1f-acef09c6166f','1b75660e-eb42-4287-8659-ff3dbc5813ea','http-https','HTTP / HTTPS','media','HTTP / HTTPS 教学动画','{\"slides\": [{\"title\": \"HTTP 协议基础\", \"narration\": \"HTTP 是超文本传输协议，基于请求-响应模型，默认端口 80。客户端发送请求，服务器返回响应。\", \"bullet_points\": [\"请求-响应模型\", \"默认端口 80\", \"无状态协议\"], \"visual_hint\": \"客户端图标（电脑）→ 箭头 → 服务器图标（机柜），箭头标注“HTTP GET /index.html”\"}, {\"title\": \"HTTP 方法\", \"narration\": \"常用方法有 GET 获取资源、POST 提交数据、PUT 更新资源、DELETE 删除资源。\", \"bullet_points\": [\"GET\", \"POST\", \"PUT\", \"DELETE\"], \"visual_hint\": \"四个图标：放大镜（GET）、信封（POST）、铅笔（PUT）、垃圾桶（DELETE）\"}, {\"title\": \"HTTPS 与 TLS\", \"narration\": \"HTTPS 在 HTTP 下加入 TLS 层，默认端口 443，通过证书和加密保证通信安全。\", \"bullet_points\": [\"TLS 加密\", \"默认端口 443\", \"数字证书验证身份\"], \"visual_hint\": \"HTTP 图标 + 锁图标 → HTTPS 图标；锁图标旁显示证书图标\"}, {\"title\": \"TLS 握手过程\", \"narration\": \"TLS 握手包括客户端发送支持的加密套件、服务器选择并发送证书、双方生成会话密钥。\", \"bullet_points\": [\"ClientHello\", \"ServerHello + 证书\", \"密钥交换\"], \"visual_hint\": \"流程图：客户端→服务器（ClientHello），服务器→客户端（ServerHello + 证书），双向箭头（密钥交换）\"}, {\"title\": \"HTTP 与 HTTPS 对比\", \"narration\": \"HTTP 明文传输，易被窃听篡改；HTTPS 加密传输，防止中间人攻击，但增加计算开销。\", \"bullet_points\": [\"明文 vs 加密\", \"无认证 vs 证书认证\", \"性能损耗\"], \"visual_hint\": \"左右对比：左侧 HTTP 图标旁有眼睛图标（窃听），右侧 HTTPS 图标旁有盾牌图标（安全）\"}], \"provider\": \"deepseek_gsap\", \"media_url\": \"\", \"knowledge_point_id\": \"http-https\", \"source_refs\": [\"planet:http-https\"], \"fallback_reason\": \"Seedance HTTP 403: {\\\"error\\\":{\\\"code\\\":\\\"AccessDenied\\\",\\\"message\\\":\\\"The request failed because you do not have access to the requested resource. Request id: 0217844249400932748f57c5f4210b3bc611acce6828c7a8a\", \"model\": \"deepseek-chat\"}','{\"model\": \"deepseek-chat\", \"slides\": [{\"title\": \"HTTP 协议基础\", \"narration\": \"HTTP 是超文本传输协议，基于请求-响应模型，默认端口 80。客户端发送请求，服务器返回响应。\", \"visual_hint\": \"客户端图标（电脑）→ 箭头 → 服务器图标（机柜），箭头标注“HTTP GET /index.html”\", \"bullet_points\": [\"请求-响应模型\", \"默认端口 80\", \