= curr->next; curr->next = prev; prev = curr; curr = next; } return prev; }\", \"explanation\": \"使用迭代法，遍历链表，将每个节点的next指向前一个节点，最后返回新的头节点。\", \"difficulty\": \"medium\"}, {\"type\": \"case\", \"question\": \"设计一个支持在任意位置插入和删除的线性表，要求插入和删除操作的时间复杂度均为O(1)，你会选择数组还是链表？请说明理由。\", \"answer\": \"链表\", \"explanation\": \"数组在插入和删除时需要移动大量元素，时间复杂度为O(n)；而链表只需修改指针，时间复杂度为O(1)。\", \"difficulty\": \"medium\"}]}','{\"quality\": {\"accuracy\": 5, \"rationale\": \"知识准确，题目覆盖数组和链表核心概念，难度适中，适合有基础的学生，但缺少与AI背景的深度结合。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"questions\": [{\"type\": \"choice\", \"answer\": \"O(1)\", \"options\": [\"O(1)\", \"O(n)\", \"O(log n)\", \"O(n^2)\"], \"question\": \"在数组中，访问第i个元素的时间复杂度是多少？\", \"difficulty\": \"easy\", \"explanation\": \"数组支持随机访问，通过下标可以直接计算出元素地址，因此时间复杂度为O(1)。\"}, {\"type\": \"blank\", \"answer\": \"指针\", \"question\": \"链表中的每个节点包含数据域和____域。\", \"difficulty\": \"easy\", \"explanation\": \"链表节点由数据域和指针域组成，指针域指向下一个节点。\"}, {\"type\": \"code\", \"answer\": \"ListNode* reverseList(ListNode* head) { ListNode* prev = nullptr; ListNode* curr = head; while (curr) { ListNode* next = curr->next; curr->next = prev; prev = curr; curr = next; } return prev; }\", \"question\": \"给定一个单链表，请写出反转链表的函数实现。函数签名：ListNode* reverseList(ListNode* head)\", \"difficulty\": \"medium\", \"explanation\": \"使用迭代法，遍历链表，将每个节点的next指向前一个节点，最后返回新的头节点。\"}, {\"type\": \"case\", \"answer\": \"链表\", \"question\": \"设计一个支持在任意位置插入和删除的线性表，要求插入和删除操作的时间复杂度均为O(1)，你会选择数组还是链表？请说明理由。\", \"difficulty\": \"medium\", \"explanation\": \"数组在插入和删除时需要移动大量元素，时间复杂度为O(n)；而链表只需修改指针，时间复杂度为O(1)。\"}]}','2026-07-18 01:11:15'),('3049d6a4-4910-492d-a694-0e8d95f479d1','12f4a817-95a2-4e0d-b3c6-4d0f3a28fbd2','osi-model','OSI 七层模型','quiz','OSI 七层模型 练习题','{\"questions\": [{\"type\": \"choice\", \"question\": \"OSI七层模型中，哪一层负责路由选择和数据包转发？\", \"options\": [\"物理层\", \"数据链路层\", \"网络层\", \"传输层\"], \"answer\": \"网络层\", \"explanation\": \"网络层负责路由选择、数据包转发和网络互联，对应OSI模型的第三层。\", \"difficulty\": \"easy\"}, {\"type\": \"blank\", \"question\": \"OSI七层模型中，______层负责建立、管理和终止会话。\", \"options\": [], \"answer\": \"会话\", \"explanation\": \"会话层（Session Layer）是OSI模型的第五层，负责建立、管理和终止应用程序之间的会话。\", \"difficulty\": \"easy\"}, {\"type\": \"essay\", \"question\": \"简述OSI七层模型中每一层的主要功能，并说明分层设计的好处。\", \"options\": [], \"answer\": \"OSI七层模型从下到上依次为：物理层（传输比特流）、数据链路层（帧传输和差错控制）、网络层（路由和分组转发）、传输层（端到端可靠传输）、会话层（会话管理）、表示层（数据格式转换和加密）、应用层（用户接口）。分层设计的好处包括：降低复杂性、标准化接口、易于实现和维护、促进互操作性、便于更新和升级。\", \"explanation\": \"OSI模型的分层结构使得网络通信的每个层次独立工作，简化了设计和实现。\", \"difficulty\": \"medium\"}, {\"type\": \"code\", \"question\": \"编写一个Python函数，模拟OSI模型中数据封装的过程：输入应用层数据（字符串），依次添加传输层、网络层、数据链路层和物理层的头部（分别用\'[TCP]\', \'[IP]\', \'[MAC]\', \'[PHY]\'表示），最后返回封装后的数据。\", \"options\": [], \"answer\": \"def encapsulate(data):\\n    return \'[PHY][MAC][IP][TCP]\' + data\", \"explanation\": \"该函数按照OSI模型从上层到下层依次添加头部，物理层在最外层。实际封装顺序为应用层数据→传输层头部→网络层头部→数据链路层头部→物理层头部。\", \"difficulty\": \"easy\"}], \"quiz_types\": [\"choice\", \"blank\", \"essay\", \"code\"]}','{\"quality\": {\"accuracy\": 5, \"rationale\": \"知识点准确，题目覆盖各层功能，难度适合大学生，结构完整，无幻觉风险。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"questions\": [{\"type\": \"choice\", \"answer\": \"网络层\", \"options\": [\"物理层\", \"数据链路层\", \"网络层\", \"传输层\"], \"question\": \"OSI七层模型中，哪一层负责路由选择和数据包转发？\", \"difficulty\": \"easy\", \"explanation\": \"网络层负责路由选择、数据包转发和网络互联，对应OSI模型的第三层。\"}, {\"type\": \"blank\", \"answer\": \"会话\", \"options\": [], \"question\": \"OSI七层模型中，______层负责建立、管理和终止会话。\", \"difficulty\": \"easy\", \"explanation\": \"会话层（Session Layer）是OSI模型的第五层，负责建立、管理和终止应用程序之间的会话。\"}, {\"type\": \"essay\", \"answer\": \"OSI七层模型从下到上依次为：物理层（传输比特流）、数据链路层（帧传输和差错控制）、网络层（路由和分组转发）、传输层（端到端可靠传输）、会话层（会话管理）、表示层（数据格式转换和加密）、应用层（用户接口）。分层设计的好处包括：降低复杂性、标准化接口、易于实现和维护、促进互操作性、便于更新和升级。\", \"options\": [], \"question\": \"简述OSI七层模型中每一层的主要功能，并说明分层设计的好处。\", \"difficulty\": \"medium\", \"explanation\": \"OSI模型的分层结构使得网络通信的每个层次独立工作，简化了设计和实现。\"}, {\"type\": \"code\", \"answer\": \"def encapsulate(data):\\n    return \'[PHY][MAC][IP][TCP]\' + data\", \"options\": [], \"question\": \"编写一个Python函数，模拟OSI模型中数据封装的过程：输入应用层数据（字符串），依次添加传输层、网络层、数据链路层和物理层的头部（分别用\'[TCP]\', \'[IP]\', \'[MAC]\', \'[PHY]\'表示），最后返回封装后的数据。\", \"difficulty\": \"easy\", \"explanation\": \"该函数按照OSI模型从上层到下层依次添加头部，物理层在最外层。实际封装顺序为应用层数据→传输层头部→网络层头部→数据链路层头部→物理层头部。\"}], \"quiz_types\": [\"choice\", \"blank\", \"essay\", \"code\"]}','2026-07-30 17:02:28'),('342cfe3a-38ed-411a-b268-f1c58d02d329','12f4a817-95a2-4e0d-b3c6-4d0f3a28fbd2','osi-model','OSI 七层模型','quiz','OSI 七层模型 练习题','{\"questions\": [{\"type\": \"choice\", \"question\": \"OSI 七层模型中，负责路由选择的是哪一层？\", \"options\": [\"物理层\", \"数据链路层\", \"网络层\", \"传输层\"], \"answer\": \"网络层\", \"explanation\": \"网络层负责数据包的路由选择和转发，实现端到端的通信。\", \"difficulty\": \"easy\"}, {\"type\": \"blank\", \"question\": \"OSI 模型中，数据链路层的传输单位是______。\", \"options\": null, \"answer\": \"帧\", \"explanation\": \"数据链路层将网络层的IP数据报封装成帧，以便在物理链路上传输。\", \"difficulty\": \"easy\"}, {\"type\": \"code\", \"question\": \"假设一个HTTP请求经过OSI模型封装，写出从应用层到物理层的封装顺序（用层名称表示，用箭头连接）。\", \"options\": null, \"answer\": \"应用层→表示层→会话层→传输层→网络层→数据链路层→物理层\", \"explanation\": \"数据封装从应用层开始，逐层添加头部，最终在物理层以比特流形式传输。\", \"difficulty\": \"medium\"}, {\"type\": \"case\", \"question\": \"用户A向用户B发送一封电子邮件。请分析在OSI模型中，传输层和网络层分别起到什么作用？\", \"options\": null, \"answer\": \"传输层负责端到端的可靠传输（如TCP），确保邮件数据完整到达；网络层负责路由选择，将数据包从A的网络发送到B的网络。\", \"explanation\": \"传输层提供进程间通信，网络层提供主机间通信。\", \"difficulty\": \"hard\"}]}','{\"quality\": {\"accuracy\": 5, \"rationale\": \"题目准确覆盖OSI模型核心概念，难度递进，适合大学生；无幻觉风险。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"questions\": [{\"type\": \"choice\", \"answer\": \"网络层\", \"options\": [\"物理层\", \"数据链路层\", \"网络层\", \"传输层\"], \"question\": \"OSI 七层模型中，负责路由选择的是哪一层？\", \"difficulty\": \"easy\", \"explanation\": \"网络层负责数据包的路由选择和转发，实现端到端的通信。\"}, {\"type\": \"blank\", \"answer\": \"帧\", \"options\": null, \"question\": \"OSI 模型中，数据链路层的传输单位是______。\", \"difficulty\": \"easy\", \"explanation\": \"数据链路层将网络层的IP数据报封装成帧，以便在物理链路上传输。\"}, {\"type\": \"code\", \"answer\": \"应用层→表示层→会话层→传输层→网络层→数据链路层→物理层\", \"options\": null, \"question\": \"假设一个HTTP请求经过OSI模型封装，写出从应用层到物理层的封装顺序（用层名称表示，用箭头连接）。\", \"difficulty\": \"medium\", \"explanation\": \"数据封装从应用层开始，逐层添加头部，最终在物理层以比特流形式传输。\"}, {\"type\": \"case\", \"answer\": \"传输层负责端到端的可靠传输（如TCP），确保邮件数据完整到达；网络层负责路由选择，将数据包从A的网络发送到B的网络。\", \"options\": null, \"question\": \"用户A向用户B发送一封电子邮件。请分析在OSI模型中，传输层和网络层分别起到什么作用？\", \"difficulty\": \"hard\", \"explanation\": \"传输层提供进程间通信，网络层提供主机间通信。\"}]}','2026-07-30 16:48:12'),('3a259be8-7372-409b-b683-f59b7ae6c932','12f4a817-95a2-4e0d-b3c6-4d0f3a28fbd2','osi-model','OSI 七层模型','quiz','OSI 七层模型 练习题','{\"questions\": [{\"type\": \"choice\", \"question\": \"OSI 七层模型中，哪一层负责将数据包从源主机路由到目标主机？\", \"options\": [\"物理层\", \"数据链路层\", \"网络层\", \"传输层\"], \"answer\": \"网络层\", \"explanation\": \"网络层负责路由选择和数据包转发，实现端到端的通信。\", \"difficulty\": \"easy\"}, {\"type\": \"blank\", \"question\": \"OSI 模型中，负责建立、管理和终止会话的层是______层。\", \"answer\": \"会话\", \"explanation\": \"会话层负责建立、管理和终止应用程序之间的会话。\", \"difficulty\": \"medium\"}, {\"type\": \"code\", \"question\": \"假设一个数据包在传输层被封装成 TCP 段，然后传递给网络层。网络层添加 IP 头部后，数据单元称为？\", \"answer\": \"IP 数据报\", \"explanation\": \"网络层封装后的数据单元称为 IP 数据报（或分组）。\", \"difficulty\": \"medium\"}, {\"type\": \"case\", \"question\": \"用户 A 向用户 B 发送一封电子邮件。描述该邮件从发送到接收经过的 OSI 各层过程（从上到下，再从下到上）。\", \"answer\": \"发送端：应用层（邮件协议）→表示层（加密/编码）→会话层（会话管理）→传输层（TCP分段）→网络层（IP路由）→数据链路层（帧封装）→物理层（比特流）。接收端反向。\", \"explanation\": \"数据在发送端逐层封装，接收端逐层解封装。\", \"difficulty\": \"hard\"}]}','{\"quality\": {\"accuracy\": 5, \"rationale\": \"知识点准确，题型多样，难度递进，适合大学生；无幻觉风险。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"questions\": [{\"type\": \"choice\", \"answer\": \"网络层\", \"options\": [\"物理层\", \"数据链路层\", \"网络层\", \"传输层\"], \"question\": \"OSI 七层模型中，哪一层负责将数据包从源主机路由到目标主机？\", \"difficulty\": \"easy\", \"explanation\": \"网络层负责路由选择和数据包转发，实现端到端的通信。\"}, {\"type\": \"blank\", \"answer\": \"会话\", \"question\": \"OSI 模型中，负责建立、管理和终止会话的层是______层。\", \"difficulty\": \"medium\", \"explanation\": \"会话层负责建立、管理和终止应用程序之间的会话。\"}, {\"type\": \"code\", \"answer\": \"IP 数据报\", \"question\": \"假设一个数据包在传输层被封装成 TCP 段，然后传递给网络层。网络层添加 IP 头部后，数据单元称为？\", \"difficulty\": \"medium\", \"explanation\": \"网络层封装后的数据单元称为 IP 数据报（或分组）。\"}, {\"type\": \"case\", \"answer\": \"发送端：应用层（邮件协议）→表示层（加密/编码）→会话层（会话管理）→传输层（TCP分段）→网络层（IP路由）→数据链路层（帧封装）→物理层（比特流）。接收端反向。\", \"question\": \"用户 A 向用户 B 发送一封电子邮件。描述该邮件从发送到接收经过的 OSI 各层过程（从上到下，再从下到上）。\", \"difficulty\": \"hard\", \"explanation\": \"数据在发送端逐层封装，接收端逐层解封装。\"}]}','2026-07-30 16:48:03'),('3a908c2f-9aae-4d4a-a862-a0871d2186d6','12f4a817-95a2-4e0d-b3c6-4d0f3a28fbd2','osi-model','OSI 七层模型','doc','OSI 七层模型 讲解文档','# OSI 七层模型：计算机网络的“星际通信协议”\n\n## 核心概念\n\nOSI（Open System Interconnection，开放系统互连）七层模型是一个**概念性框架**，它将计算机网络通信过程划分为七个层次。其核心思想是**分层**：每一层负责特定的通信功能，层与层之间通过明确的接口进行交互。这种分层结构使得网络设计、开发和维护更加模块化、标准化。\n\n- **分层原则**：每一层都为其上一层提供服务，并依赖下一层提供的服务。数据从发送方的顶层（应用层）向下传输，经过每一层处理后到达物理层，通过网络介质传输到接收方，再从接收方的物理层向上传输，最终到达顶层。\n- **层次名称**（从上到下）：应用层、表示层、会话层、传输层、网络层、数据链路层、物理层。\n- **关键特性**：每一层独立工作，修改某一层的实现不影响其他层，这类似于软件工程中的“高内聚、低耦合”设计。\n\n## 原理讲解\n\n理解OSI模型的关键在于掌握**数据封装**和**层间交互**的过程。\n\n1.  **数据封装过程**：\n    - 当发送方应用程序发送数据（如一个网页请求）时，数据从**应用层**开始，逐层向下传递。\n    - 每一层都会在数据上添加自己的**头部信息**（有时也添加尾部），这个过程称为封装。例如，传输层添加端口号，网络层添加IP地址，数据链路层添加MAC地址。\n    - 最终，**物理层**将封装后的比特流（0和1）通过物理介质（如网线、光纤）发送出去。\n\n2.  **层间交互与递归思想**：\n    - 这类似于数据结构中的**递归调用**。如参考资料中所述：“从第 i 层递归调用本函数为进入‘下一层’，即第 i+1 层。反之，退出第 i 层递归应返回至‘上一层’”（《严蔚敏 数据结构（C语言版）》p.66）。\n    - 在OSI模型中，数据从第N层传递到第N-1层（向下），可以看作一次“递归调用”；而数据从第N-1层返回第N层（向上），则是“递归返回”。每一层都像一个独立的函数，处理完自己的任务后，将结果传递给下一层。\n    - 例如，**传输层**（第4层）将数据段传递给**网络层**（第3层），网络层添加IP头部后交给**数据链路层**（第2层），数据链路层添加MAC头部后交给**物理层**（第1层）。接收方则反向进行，从物理层逐层“返回”到应用层。\n\n3.  **各层职责简述**（自上而下）：\n    - **应用层**：直接为应用程序提供网络服务，如HTTP（网页浏览）、FTP（文件传输）。\n    - **表示层**：处理数据格式转换、加密解密、压缩解压，确保不同系统能理解数据。\n    - **会话层**：管理会话，建立、维护和终止应用程序之间的通信连接。\n    - **传输层**：提供端到端的可靠或不可靠传输（如TCP/UDP），负责数据分段、流量控制和错误恢复。\n    - **网络层**：负责数据包的路由选择（寻址）和转发，核心协议是IP。\n    - **数据链路层**：负责在相邻节点间传输数据帧，进行差错检测和物理地址（MAC地址）寻址。\n    - **物理层**：负责传输原始的比特流，定义物理接口的电气、机械特性。\n\n## 案例\n\n**场景：访问一个网页**\n\n假设你在浏览器中输入 `www.example.com` 并按下回车，这个过程完美展示了OSI七层模型的工作：\n\n1.  **应用层**：浏览器（应用层）发起一个HTTP请求，请求数据为“GET /index.html”。\n2.  **表示层**：将HTTP请求数据可能进行编码或加密（如HTTPS中的SSL/TLS加密）。\n3.  **会话层**：建立与服务器之间的会话连接，管理本次通信的会话状态。\n4.  **传输层**：将HTTP请求封装成TCP数据段，添加源端口（如随机端口12345）和目的端口（80），并保证数据可靠传输。\n5.  **网络层**：将TCP数据段封装成IP数据包，添加源IP地址（你的电脑IP）和目的IP地址（`www.example.com`的服务器IP）。\n6.  **数据链路层**：将IP数据包封装成数据帧，添加源MAC地址（你的网卡MAC）和目的MAC地址（路由器或网关的MAC），并进行差错校验。\n7.  **物理层**：将数据帧转换成比特流，通过网线或Wi-Fi信号发送出去。\n\n接收方（服务器）则进行反向操作，从物理层逐层向上“解封装”，最终将HTTP请求提交给服务器软件，服务器处理请求后，再通过同样的分层过程将网页数据返回给你的浏览器。\n\n## 总结\n\nOSI七层模型是计算机网络领域的**基础性理论框架**。它通过**分层**思想，将复杂的网络通信过程分解为七个独立的、功能明确的层次，每一层都专注于自己的任务，并依赖相邻层提供服务。\n\n- **核心价值**：提供了**标准化**的通信模型，使得不同厂商的网络设备能够互操作；**模块化**设计便于网络系统的开发、排错和优化。\n- **与递归的类比**：数据在层间的传递过程类似于递归调用中的“进入下一层”和“返回上一层”，每一层都是独立且功能完整的“函数”（参考《严蔚敏 数据结构》p.66的递归思想）。\n- **学习意义**：掌握OSI模型，是理解TCP/IP协议栈、网络设备工作原理（如交换机工作在数据链路层，路由器工作在网络层）以及网络故障排查（如物理层故障导致“网络不通”）的基石。\n\n**一句话总结：OSI七层模型是计算机网络的“语法规则”，它定义了数据如何从你的电脑出发，穿越星际般的互联网，最终到达目的地。**','{\"quality\": {\"accuracy\": 4, \"rationale\": \"内容准确，结构完整，案例清晰，但将OSI模型类比为递归调用略显牵强，可能造成误解。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 2}}','2026-07-30 16:51:52'),('3c547cc7-ad16-44e5-aca4-399616ef96ae','1b75660e-eb42-4287-8659-ff3dbc5813ea','udp-protocol','UDP 协议','reading','UDP 协议 拓展阅读','{\"materials\": [{\"title\": \"UDP vs TCP: 核心区别与适用场景\", \"summary\": \"对比UDP和TCP协议，重点分析UDP的无连接、不可靠特性及其在实时应用中的优势。\", \"keywords\": [\"UDP\", \"TCP\", \"无连接\", \"实时传输\"], \"difficulty\": \"medium\"}, {\"title\": \"UDP 数据包结构与校验和\", \"summary\": \"详细解析UDP头部格式（源端口、目的端口、长度、校验和）及校验和计算过程。\", \"keywords\": [\"UDP头部\", \"校验和\", \"数据包结构\"], \"difficulty\": \"medium\"}, {\"title\": \"UDP 在流媒体与实时通信中的应用\", \"summary\": \"探讨UDP在视频直播、VoIP、在线游戏等场景下的应用，以及如何通过应用层实现可靠性。\", \"keywords\": [\"流媒体\", \"VoIP\", \"实时通信\", \"可靠性\"], \"difficulty\": \"hard\"}], \"article\": \"## UDP 协议深度解析\\n\\nUDP（User Datagram Protocol，用户数据报协议）是一种无连接的传输层协议，位于IP层之上。与TCP不同，UDP不提供可靠性、流量控制或拥塞控制，但具有低延迟和低开销的优势，适用于对实时性要求高、允许少量丢包的应用。\\n\\n### 核心特性\\n\\n- **无连接**：发送数据前无需建立连接，减少了握手开销，适合快速发送小数据包。\\n- **不可靠**：UDP不保证数据包按序到达、不重传丢失包，也不进行拥塞控制。\\n- **面向报文**：UDP保留应用层消息边界，每个UDP数据报对应一个应用层报文。\\n- **轻量级**：头部仅8字节（源端口、目的端口、长度、校验和），比TCP的20字节更小。\\n\\n### 数据包结构\\n\\nUDP头部包含四个字段：\\n- 源端口（16位）：可选，用于标识发送进程。\\n- 目的端口（16位）：必填，用于标识接收进程。\\n- 长度（16位）：UDP数据报总长度（头部+数据），最小8字节。\\n- 校验和（16位）：可选，用于检测传输错误，覆盖伪头部、UDP头部和数据。\\n\\n### 校验和计算\\n\\n校验和计算时，首先构造一个伪头部（包含源IP、目的IP、协议号、UDP长度），然后对伪头部、UDP头部和数据按16位进行反码求和。若校验和为0，则发送方将其设为全1。接收方验证校验和，若错误则丢弃数据报（不通知发送方）。\\n\\n### 典型应用\\n\\n- **DNS查询**：使用UDP 53端口，快速响应，单个查询通常小于512字节。\\n- **视频流与直播**：如RTSP、RTP基于UDP，容忍少量丢包以降低延迟。\\n- **VoIP**：如SIP和RTP，实时语音通信对延迟敏感。\\n- **在线游戏**：状态更新频繁，UDP减少延迟。\\n\\n### 应用层可靠性增强\\n\\n由于UDP不可靠，应用层可自行实现可靠性机制：\\n- **超时重传**：发送方设置定时器，超时未收到ACK则重传。\\n- **序列号与确认**：类似TCP的序列号机制。\\n- **流量控制**：基于接收方缓冲区容量调整发送速率。\\n\\n### 总结\\n\\nUDP是简单高效的传输协议，适合实时应用。理解其无连接、不可靠的特性，以及校验和机制，有助于在网络编程中正确选择协议。\"}','{\"article\": \"## UDP 协议深度解析\\n\\nUDP（User Datagram Protocol，用户数据报协议）是一种无连接的传输层协议，位于IP层之上。与TCP不同，UDP不提供可靠性、流量控制或拥塞控制，但具有低延迟和低开销的优势，适用于对实时性要求高、允许少量丢包的应用。\\n\\n### 核心特性\\n\\n- **无连接**：发送数据前无需建立连接，减少了握手开销，适合快速发送小数据包。\\n- **不可靠**：UDP不保证数据包按序到达、不重传丢失包，也不进行拥塞控制。\\n- **面向报文**：UDP保留应用层消息边界，每个UDP数据报对应一个应用层报文。\\n- **轻量级**：头部仅8字节（源端口、目的端口、长度、校验和），比TCP的20字节更小。\\n\\n### 数据包结构\\n\\nUDP头部包含四个字段：\\n- 源端口（16位）：可选，用于标识发送进程。\\n- 目的端口（16位）：必填，用于标识接收进程。\\n- 长度（16位）：UDP数据报总长度（头部+数据），最小8字节。\\n- 校验和（16位）：可选，用于检测传输错误，覆盖伪头部、UDP头部和数据。\\n\\n### 校验和计算\\n\\n校验和计算时，首先构造一个伪头部（包含源IP、目的IP、协议号、UDP长度），然后对伪头部、UDP头部和数据按16位进行反码求和。若校验和为0，则发送方将其设为全1。接收方验证校验和，若错误则丢弃数据报（不通知发送方）。\\n\\n### 典型应用\\n\\n- **DNS查询**：使用UDP 53端口，快速响应，单个查询通常小于512字节。\\n- **视频流与直播**：如RTSP、RTP基于UDP，容忍少量丢包以降低延迟。\\n- **VoIP**：如SIP和RTP，实时语音通信对延迟敏感。\\n- **在线游戏**：状态更新频繁，UDP减少延迟。\\n\\n### 应用层可靠性增强\\n\\n由于UDP不可靠，应用层可自行实现可靠性机制：\\n- **超时重传**：发送方设置定时器，超时未收到ACK则重传。\\n- **序列号与确认**：类似TCP的序列号机制。\\n- **流量控制**：基于接收方缓冲区容量调整发送速率。\\n\\n### 总结\\n\\nUDP是简单高效的传输协议，适合实时应用。理解其无连接、不可靠的特性，以及校验和机制，有助于在网络编程中正确选择协议。\", \"quality\": {\"accuracy\": 5, \"rationale\": \"内容准确全面，结构清晰，难度适中，与AI专业背景匹配，无幻觉风险。\", \"scored_by\": \"deepseek\", \"profile_fit\": 4, \"completeness\": 5, \"needs_review\": false, \"should_retry\": false, \"hallucination_risk\": 1}, \"materials\": [{\"title\": \"UDP vs TCP: 核心区别与适用场景\", \"summary\": \"对比UDP和TCP协议，重点分析UDP的无连接、不可靠特性及其在实时应用中的优势。\", \"keywords\": [\"UDP\", \"TCP\", \"无连接\", \"实时传输\"], \"difficulty\": \"medium\"}, {\"title\": \"UDP 数据包结构与校验和\", \"summary\": \"详细解析UDP头部格式（源端口、目的端口、长度、校验和）及校验和计算过程。\", \"keywords\": [\"UDP头部\", \"校验和\", \"数据包结构\"], \"difficulty\": \"medium\"}, {\"title\": \"UDP 在流媒体与实时通信中的应用\", \"summary\": \"探讨UDP在视频直播、VoIP、在线游戏等场景下的应用，以及如何通过应用层实现可靠性。\", \"keywords\": [\"流媒体\", \"VoIP\", \"实时通信\", \"可靠性\"], \"difficulty\": \"hard\"}]}','2026-07-18 11:55:26'),('3ee90fa4-733b-46b0-9aa2-d6d74347d085','1b75660e-eb42-4287-8659-ff3dbc5813ea','http-https','HTTP / HTTPS','media','HTTP / HTTPS 教学动画','{\"slides\": [{\"title\": \"HTTP 基础\", \"narration\": \"HTTP是超文本传输协议，客户端发送请求，服务器返回响应。请求包含方法、URL、头部和可选正文。\", \"bullet_points\": [\"请求-响应模型\", \"常用方法：GET、POST\", \"无状态协议\"], \"visual_hint\": \"客户端图标（电脑）与服务器图标（机柜）之间箭头标注“请求”和“响应”，旁边列出GET/POST标签。\"}, {\"title\": \"HTTPS 与 TLS\", \"narration\": \"HTTPS在HTTP下加入TLS加密层，保护数据机密性和完整性。通过证书验证服务器身份。\", \"bullet_points\": [\"TLS握手\", \"证书认证\", \"对称+非对称加密\"], \"visual_hint\": \"HTTP层与TLS层叠加的协议栈图，锁形图标表示加密，证书图标（文档带印章）表示身份验证。\"}, {\"title\": \"TLS 握手过程\", \"narration\": \"客户端发起ClientHello，服务器回复ServerHello和证书。双方交换密钥参数，生成会话密钥。\", \"bullet_points\": [\"ClientHello\", \"ServerHello+证书\", \"密钥交换与确认\"], \"visual_hint\": \"时序图：左右两个竖线（客户端、服务器），从上到下依次标注ClientHello、ServerHello、证书、密钥交换、完成。\"}, {\"title\": \"HTTP 与 HTTPS 对比\", \"narration\": \"HTTP明文传输，易被窃听和篡改；HTTPS加密传输，安全但增加握手延迟和计算开销。\", \"bullet_points\": [\"安全性差异\", \"性能开销\", \"默认端口80 vs 443\"], \"visual_hint\": \"左右对比图：左侧HTTP（无锁图标，端口80），右侧HTTPS（锁图标，端口443），中间箭头标注“加密”。\"}, {\"title\": \"实践：配置 HTTPS\", \"narration\": \"获取证书并配置Web服务器。常用工具如Let\'s Encrypt提供免费证书，Nginx/Apache支持一键启用。\", \"bullet_points\": [\"申请证书\", \"配置服务器\", \"测试与验证\"], \"visual_hint\": \"流程图：浏览器→服务器→证书颁发机构（CA），服务器内部显示Nginx/Apache配置界面。\"}], \"provider\": \"deepseek_gsap\", \"media_url\": \"\", \"knowledge_point_id\": \"http-https\", \"source_refs\": [\"planet:http-https\"], \"fallback_reason\": \"Seedance HTTP 403: {\\\"error\\\":{\\\"code\\\":\\\"AccessDenied\\\",\\\"message\\\":\\\"The request failed because you do not have access to the requested resource. Request id: 02178442466411037079cdcc08b35ab782b1fd6e8da4cf014\", \"model\": \"deepseek-chat\"}','{\"model\": \"deepseek-chat\", \"slides\": [{\"title\": \"HTTP 基础\", \"narration\": \"HTTP是超文本传输协议，客户端发送请求，服务器返回响应。请求包含方法、URL、头部和可选正文。\", \"visual_hint\": \"客户端图标（电脑）与服务器图标（机柜）之间箭头标注“请求”和“响应”，旁边列出GET/POST标签。\", \"bullet_points\": [\"请求-响应模型\", \"常用方法：GET、POST\", \"无状态协议\"]}, {\"title\": \"HTTPS 与 TLS\", \"narration\": \"HTTPS在HTTP下加入TLS加密层，保护数据机密性和完整性。通过证书验证服务器身份。\", \"visual_hint\": \"HTTP层与TLS层叠加的协议栈图，锁形图标表示加密，证书图标（文档带印章）表示身份验证。\", \"bullet_points\": [\"TLS握手\", \"证书认证\", \"对称+非对称加密\"]}, {\"title\": \"TLS 握手过程\", \"narration\": \"客户端发起ClientHello，服务器回复ServerHello和证书。双方交换密钥参数，生成会话密钥。\", \"visual_hint\": \"时序图：左右两个竖线（客户端、服务器），从上到下依次标注ClientHello、ServerHello、证书、密钥交换、完成。\", \"bullet_points\": [\"ClientHello\", \"ServerHello+证书\", \"密钥交换与确认\"]}, {\"title\": \"HTTP 与 HTTPS 对比\", \"narration\": \"HTTP明文传输，易被窃听和篡改；HTTPS加密传输，安全但增加握手延迟和计算开销。\", \"visual_hint\": \"左右对比图：左侧HTTP（无锁图标，端口80），右侧HTTPS（锁图标，端口443），中间箭头标注“加密”。\", \"bullet_points\": [\"安全性差异\", \"性能开销\", \"默认端口80 vs 443\"]}, {\"title\": \"实践：配置 HTTPS\", 