  `teacher_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `class_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `challenge_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `planet_slug` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `planet_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `knowledge_point_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cited_knowledge_point_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidence` float NOT NULL,
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_preview` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resolved` tinyint(1) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `ix_hallucination_tickets_class_id` (`class_id`),
  KEY `ix_hallucination_tickets_student_id` (`student_id`),
  KEY `ix_hallucination_tickets_challenge_id` (`challenge_id`),
  KEY `ix_hallucination_tickets_teacher_id` (`teacher_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
