INSERT INTO `learning_paths` VALUES ('2e3f046c-8832-4270-9adc-84ef6920459b','1b75660e-eb42-4287-8659-ff3dbc5813ea','高等数学基础学习路径','[{\"action\": \"学习\", \"reason\": \"导数是微积分的基础，必须先掌握\", \"planet_name\": \"导数与微分\", \"planet_slug\": \"derivative\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"学习\", \"reason\": \"积分与导数紧密相关，是高等数学的核心\", \"planet_name\": \"不定积分与定积分\", \"planet_slug\": \"integral\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"学习\", \"reason\": \"从一元到多元的扩展，深化理解\", \"planet_name\": \"多元函数微分\", \"planet_slug\": \"multivariable\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"复习\", \"reason\": \"已有基础，通过复习巩固并应用于高等数学\", \"planet_name\": \"矩阵与行列式\", \"planet_slug\": \"matrix\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"复习\", \"reason\": \"已有基础，快速复习以保持知识连贯\", \"planet_name\": \"栈与队列\", \"planet_slug\": \"stack-queue\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"学习\", \"reason\": \"了解调度算法，培养逻辑思维\", \"planet_name\": \"CPU 调度\", \"planet_slug\": \"cpu-scheduling\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}]','active','2026-07-19 10:23:06'),('435b4284-2997-434f-99f5-dcb026c9cf09','1b75660e-eb42-4287-8659-ff3dbc5813ea','数据结构复习路径','[{\"action\": \"复习基础概念与操作\", \"reason\": \"薄弱行星，分数72，需巩固基础\", \"planet_name\": \"栈与队列\", \"planet_slug\": \"stack-queue\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"完成专项练习题，重点攻克错题\", \"reason\": \"评估建议针对错题专项复习\", \"planet_name\": \"栈与队列\", \"planet_slug\": \"stack-queue\", \"resource_kinds\": [\"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"复习线性代数基础，重点理解矩阵运算\", \"reason\": \"薄弱行星，分数72，为数据结构中矩阵应用打基础\", \"planet_name\": \"矩阵与行列式\", \"planet_slug\": \"matrix\", \"resource_kinds\": [\"doc\", \"quiz\"], \"estimated_minutes\": 30}, {\"action\": \"完成矩阵相关应用题，结合数据结构场景\", \"reason\": \