INSERT INTO `notes` VALUES ('c73b3990-6d04-470b-9ff5-8ec45e3ad6be','1b75660e-eb42-4287-8659-ff3dbc5813ea','array-linkedlist','划词 · 数据结构题集 严蔚敏 C语言版','（画笔框选区域）','','2026-07-30 06:13:12','2026-07-30 06:13:12','[{\"at\": \"2026-07-30T06:13:12.399439+00:00\", \"kind\": \"quote\", \"text\": \"（画笔框选区域）\", \"source\": \"starlib\", \"page_no\": 1, \"asset_id\": \"78c185e4-073c-4ce0-bb7b-29e29f95e82b\", \"has_region_image\": true}]','quote','','data-structure'),('d023e2ce-af99-4694-85d6-84a8d9a1e4cb','1b75660e-eb42-4287-8659-ff3dbc5813ea','osi-model','OSI 七层模型 · 随堂笔记','好的，这是根据您提供的知识点「OSI 七层模型」生成的结构化随堂笔记。\n\n---\n\n# 📚 随堂笔记：OSI 七层模型\n\n## 🎯 学习目标\n*   理解 OSI 七层模型的分层思想与核心作用。\n*   掌握七层名称、顺序及每层的基本功能。\n*   能够将常见的网络协议（如 HTTP、TCP、IP）对应到正确的层级。\n*   理解数据在各层之间的封装与解封装过程。\n\n## 🧠 核心要点\n\n**OSI 七层模型**（Open Systems Interconnection Model）是一个概念模型，它将计算机网络通信划分为七个层次，旨在促进不同厂商、不同系统之间的互操作性。从下到上依次为：\n\n1.  **物理层 (Physical Layer)**：负责在物理介质上传输原始的比特流（0和1）。定义了电压、线缆规格、接口形状等物理特性。\n2.  **数据链路层 (Data Link Layer)**：将比特流组装成帧（Frame），提供节点到节点的可靠传输。负责差错检测和流量控制。常见协议：**以太网 (Ethernet)**、**PPP**。\n3.  **网络层 (Network Layer)**：负责数据包（Packet）的路由选择（Routing）和转发。核心设备是**路由器**。常见协议：**IP (IPv4/IPv6)**、**ICMP**。\n4.  **传输层 (Transport Layer)**：提供端到端（进程到进程）的可靠或不可靠传输。负责数据分段、流量控制、差错恢复。常见协议：**TCP**（可靠）、**UDP**（不可靠）。\n5.  **会话层 (Session Layer)**：负责建立、管理和终止会话（Session）。例如，在文件传输中建立、维护和断开连接。\n6.  **表示层 (Presentation Layer)**：负责数据的语法表示和转换，如加密、解密、压缩、解压缩、数据格式转换（如 ASCII 与 EBCDIC）。\n7.  **应用层 (Application Layer)**：直接为应用程序提供网络服务。用户通过此层与网络交互。常见协议：**HTTP**、**FTP**、**SMTP**、**DNS**。\n\n> **记忆口诀**：物、链、网、传、会、表、应。\n\n## ⚔️ 演武关键步\n\n1.  **分层记忆**：熟记七层名称和顺序，这是所有网络通信分析的基础。\n2.  **协议归类**：能够将常见协议准确归入对应层级。\n    *   **应用层**：HTTP, HTTPS, FTP, SMTP, DNS, DHCP\n    *   **传输层**：TCP, UDP\n    *   **网络层**：IP, ICMP, ARP (ARP 通常被认为工作在数据链路层和网络层之间)\n    *   **数据链路层**：Ethernet, PPP, MAC 地址\n3.  **数据封装过程**：理解数据从应用层向下传递时，每一层都会添加自己的头部（Header），形成新的数据单元。\n    *   应用层 → 数据 (Data)\n    *   传输层 → 数据段 (Segment)\n    *   网络层 → 数据包 (Packet)\n    *   数据链路层 → 数据帧 (Frame)\n    *   物理层 → 比特流 (Bits)\n4.  **设备对应**：记住常见网络设备工作的层级。\n    *   物理层：中继器、集线器\n    *   数据链路层：交换机、网桥\n    *   网络层：路由器\n    *   传输层及以上：网关\n\n## ⚠️ 易错点\n\n*   **混淆传输层与网络层**：传输层负责**端到端**（进程到进程）的通信，而网络层负责**点到点**（主机到主机）的通信。TCP 是传输层协议，IP 是网络层协议。\n*   **混淆数据链路层与物理层**：物理层传输的是**比特流**，数据链路层传输的是**帧**。物理层不关心数据含义，只关心信号；数据链路层负责将比特流组织成有意义的帧，并进行差错检测。\n*   **认为 OSI 模型是实际协议栈**：OSI 模型是一个**概念模型**，实际互联网使用的是 **TCP/IP 协议栈**（四层或五层模型）。OSI 模型是学习和理解网络通信的理论框架。\n*   **混淆应用层协议**：例如，DNS 虽然用于域名解析，但它工作在应用层（使用 UDP 或 TCP 传输）。HTTP 是应用层协议，用于 Web 浏览。\n\n## 🔄 待复习\n\n*   [ ] 默写 OSI 七层模型名称及顺序。\n*   [ ] 列举至少 3 个应用层、传输层、网络层、数据链路层的协议。\n*   [ ] 画图说明数据从应用层到物理层的封装过程。\n*   [ ] 比较 OSI 模型与 TCP/IP 模型的异同。\n*   [ ] 解释为什么需要分层设计。\n\n---\n\n**引用页码：**\n*   [《planet_seed》] 知识点ID: osi-model, 名称: OSI 七层模型, 所属星系: 计算机网络星系 (p.1)\n*   [《seed》] 计算机网络星系 · Socket 编程 知识点 (p.2)','','2026-07-29 05:51:55','2026-07-29 05:51:55','[{\"kind\": \"ai_summary\", \"text\": \"好的，这是根据您提供的知识点「OSI 七层模型」生成的结构化随堂笔记。\\n\\n---\\n\\n# 📚 随堂笔记：OSI 七层模型\\n\\n## 🎯 学习目标\\n*   理解 OSI 七层模型的分层思想与核心作用。\\n*   掌握七层名称、顺序及每层的基本功能。\\n*   能够将常见的网络协议（如 HTTP、TCP、IP）对应到正确的层级。\\n*   理解数据在各层之间的封装与解封装过程。\\n\\n## 🧠 核心要点\\n\\n**OSI 七层模型**（Open Systems Interconnection Model）是一个概念模型，它将计算机网络通信划分为七个层次，旨在促进不同厂商、不同系统之间的互操作性。从下到上依次为：\\n\\n1.  **物理层 (Physical Layer)**：负责在物理介质上传输原始的比特流（0和1）。定义了电压、线缆规格、接口形状等物理特性。\\n2.  **数据链路层 (Data Link Layer)**：将比特流组装成帧（Frame），提供节点到节点的可靠传输。负责差错检测和流量控制。常见协议：**以太网 (Ethernet)**、**PPP**。\\n3.  **网络层 (Network La\"}]','ai_summary','','');
