DROP TABLE IF EXISTS `planets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `planets` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `galaxy_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `difficulty` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'easy/medium/hard',
  `orbit_index` int NOT NULL COMMENT '所在轨道层',
  `angle_deg` float NOT NULL COMMENT '轨道初始角度',
  `radius_offset` float NOT NULL COMMENT '轨道半径微调',
  `prerequisites` json NOT NULL COMMENT '前置行星 slug 列表',
  `question_tags` json NOT NULL COMMENT '出题标签',
  `sort_order` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_planets_slug` (`slug`),
  KEY `ix_planets_galaxy_id` (`galaxy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

