INSERT INTO `remediation_plans` VALUES ('3110ed2f-86c4-4024-bd15-abea6376b5b8','1b75660e-eb42-4287-8659-ff3dbc5813ea','run-48c383d69621','mistake_tendency','易错倾向认知澄清：粗心大意','对IP地址中数值范围（0-255）及特殊地址（如广播地址255）的认知不清晰，导致无法正确判断小明的说法错误。','[{\"done\": true, \"index\": 0, \"title\": \"第一步：复习IP地址数值范围（0-255）的基本规则，重点记忆每个字节的取值范围，并对比255作为广播地址的特殊性。\", \"evidence_text\": \"已完成\"}, {\"done\": false, \"index\": 1, \"title\": \"第二步：完成5道关于IP地址范围判断的专项练习题，例如判断\'192.168.1.256\'是否合法，并标注出每个错误选项的错因。\", \"evidence_text\": \"\"}, {\"done\": false, \"index\": 2, \"title\": \"第三步：分析小明说法中的具体错误，结合广播地址（如255.255.255.255）和普通地址的区别，写一段100字以内的解释说明。\", \"evidence_text\": \"\"}, {\"done\": false, \"index\": 3, \"title\": \"第四步：自测一道综合题：给定一个IP地址列表，快速识别并解释其中所有不符合范围或特殊地址的项，计时5分钟完成。\", \"evidence_text\": \"\"}]','open','2026-07-16 19:54:06','2026-07-30 16:05:32');
/*!40000 ALTER TABLE `remediation_plans` ENABLE KEYS */;
UNLOCK TABLES;

