DROP TABLE IF EXISTS `student_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_profiles` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `major_background` json NOT NULL COMMENT '专业背景',
  `prior_knowledge` json NOT NULL COMMENT '前置知识',
  `cognitive_style` json NOT NULL COMMENT '认知风格',
  `mistake_tendency` json NOT NULL COMMENT '易错倾向',
  `learning_goal` json NOT NULL COMMENT '学习目标',
  `time_flexibility` json NOT NULL COMMENT '时间弹性',
  `raw_evidence` json DEFAULT (json_object()),
  `follow_up_questions` json NOT NULL COMMENT '待追问维度',
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `missing_dimensions` json DEFAULT NULL,
  `user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `dimension_floors_json` json DEFAULT NULL,
  `warnings_json` json DEFAULT NULL,
  `update_source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'profiler',
  `modality_preference` json DEFAULT NULL,
  `motivation_level` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

